Load the cached values from the active sheet and scan each data row from the first month column (F) to the last month column before AO. For each row, write the first numeric value that is not zero into AO, leaving the cell empty if no such value exists. Save the modified workbook to OUT.

```python
import shutil, math
import openpyxl
from openpyxl.utils import column_index_from_string

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title] if ws.title in vals.sheetnames else vals.active

ao_col = column_index_from_string("AO")
start_col = column_index_from_string("F")
end_col = ao_col - 1

def nonzero_value(v):
    if isinstance(v, bool):
        return v if v else None

    if isinstance(v, (int, float)):
        if isinstance(v, float) and not math.isfinite(v):
            return None
        if v == 0:
            return None
        return v

    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("%"):
                f = float(s[:-1].strip()) / 100.0
            else:
                f = float(s)
            if math.isfinite(f) and f != 0:
                return f
        except ValueError:
            pass

    return None

filled = 0
for r in range(9, 1289):
    ans = None
    for c in range(start_col, end_col + 1):
        ans = nonzero_value(vws.cell(row=r, column=c).value)
        if ans is not None:
            break

    ws.cell(row=r, column=ao_col).value = ans

    if ans is not None:
        filled += 1

    if r <= 12:
        print(r, vws.cell(row=r, column=2).value, ans)

print("filled", filled, "of", 1288 - 9 + 1)
wb.save(OUT)
